def remove(self,
	           package,
	           shutit_pexpect_child=None,
	           options=None,
	           echo=None,
	           timeout=shutit_global.shutit_global_object.default_timeout,
	           note=None):
		"""Distro-independent remove function.
		Takes a package name and runs relevant remove function.

		@param package:  Package to remove, which is run through package_map.
		@param shutit_pexpect_child:    See send()
		@param options:  Dict of options to pass to the remove command,
		                 mapped by install_type.
		@param timeout:  See send(). Default: 3600
		@param note:     See send()

		@return: True if all ok (i.e. the package was successfully removed),
		         False otherwise.
		@rtype: boolean
		"""
        _child: shutit_pexpect_child from main.
                @param options: Options to pass to the remove function.
                @param echo: Echo to the console.
                @param timeout: Timeout to pass to the remove function.
                @param note: Notes to pass to the remove function.
                @return: The return value of the remove function.
                """
                if not self.package_map:
                    raise Exception('Package map not defined')
                if package not in self.package_map:
                    raise Exception('Package not found in package_map')
                return self.package_map[package](shutit_pexpect_child=shutit_pexpect_child,
                                                 options=options,
                                                 echo=echo,
                                                 timeout=timeout,
                                                 note=note)

